import{c as o,$ as i,Q as n,j as s,g as e,o as r,n as l,m as d}from"./chunks/framework.Ce_49mA8.js";const q=JSON.parse('{"title":"Investment Portfolio","description":"Practical guide to managing stocks, bonds, crypto assets, private equity, and loans in OmniCraft ERP.","frontmatter":{"title":"Investment Portfolio","description":"Practical guide to managing stocks, bonds, crypto assets, private equity, and loans in OmniCraft ERP.","datePublished":"2026-10-28","dateModified":"2026-11-15","order":16},"headers":[],"relativePath":"docs/spaces/moy-kapital/investments.md","filePath":"docs/spaces/moy-kapital/investments.md","lastUpdated":1794700800000}'),c={name:"docs/spaces/moy-kapital/investments.md"},u={id:"investment-portfolio-wealth-preservation-and-growth",tabindex:"-1"};function m(g,t,p,h,f,v){const a=i("DocIcon");return n(),s("div",null,[e("h1",u,[r(a,{name:"capital"}),t[0]||(t[0]=l(" Investment Portfolio: Wealth Preservation and Growth ",-1)),t[1]||(t[1]=e("a",{class:"header-anchor",href:"#investment-portfolio-wealth-preservation-and-growth","aria-label":'Permalink to "Investment Portfolio: Wealth Preservation and Growth"'},"​",-1))]),t[2]||(t[2]=d('<p>The <strong>Investment Portfolio</strong> tab tracks assets dedicated to the preservation and long-term expansion of the master craftsman&#39;s personal wealth. Unlike operational workshop cash and daily checking accounts, this module manages instruments with strategic horizons: publicly traded stocks, sovereign and corporate bonds, exchange-traded funds, digital reserve assets, private business equity, and peer-to-peer loans.</p><p>A disciplined investment contour forms a resilient financial cushion. Returns from external holdings protect the craft business during seasonal demand downturns, material supply delays, or major tooling upgrades.</p><hr><h2 id="_3-tier-portfolio-architecture" tabindex="-1">3-Tier Portfolio Architecture <a class="header-anchor" href="#_3-tier-portfolio-architecture" aria-label="Permalink to &quot;3-Tier Portfolio Architecture&quot;">​</a></h2><p>To ensure structured management across diverse asset types, the system implements a canonical three-tier hierarchy:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Asset Class] ➔ [Platform / Broker] ➔ [Financial Instruments]</span></span></code></pre></div><ol><li><strong>Asset Class (Group Category):</strong> top-level risk diversification bucket (<em>&quot;Equities&quot;</em>, <em>&quot;Bonds &amp; Funds&quot;</em>, <em>&quot;Cryptocurrency&quot;</em>, <em>&quot;Private Equity&quot;</em>, <em>&quot;Loans Issued&quot;</em>).</li><li><strong>Platform / Broker (Asset Group):</strong> specific custody institution (<em>&quot;Primary Broker&quot;</em>, <em>&quot;Hardware Cold Wallet&quot;</em>, <em>&quot;Workshop Venture Project&quot;</em>).</li><li><strong>Financial Instruments (Positions):</strong> individual holdings with recorded cost basis, current market valuation, and currency (<em>&quot;Apple Inc. (AAPL)&quot;</em>, <em>&quot;Treasury Bond 2030&quot;</em>, <em>&quot;Bitcoin&quot;</em>, <em>&quot;25% Studio Equity&quot;</em>).</li></ol><hr><h2 id="portfolio-indicators-and-allocation-bar" tabindex="-1">Portfolio Indicators and Allocation Bar <a class="header-anchor" href="#portfolio-indicators-and-allocation-bar" aria-label="Permalink to &quot;Portfolio Indicators and Allocation Bar&quot;">​</a></h2><p>The top command center presents real-time aggregate performance indicators:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Chart Icon] TOTAL PORTFOLIO: $ 45,000.00  |  Invested: $ 38,000.00  |  Return: +$ 7,000.00 (+18.4%)</span></span></code></pre></div><ul><li><strong>&quot;Total Portfolio&quot;:</strong> aggregate market value of all investment positions converted to base currency;</li><li><strong>&quot;Invested Capital&quot;:</strong> actual personal funds deployed into acquiring assets;</li><li><strong>&quot;Financial Return&quot;:</strong> accumulated net profit or unrealized capital gain in currency and percentage yield (gains highlighted in green, drawdowns in alert red).</li></ul><h3 id="portfolio-allocation-bar" tabindex="-1">Portfolio Allocation Bar <a class="header-anchor" href="#portfolio-allocation-bar" aria-label="Permalink to &quot;Portfolio Allocation Bar&quot;">​</a></h3><p>Directly beneath the numerical KPIs sits a multi-segment colored allocation bar:</p><ul><li>Each segment matches the distinct theme color of its asset class;</li><li>Segment length reflects the class&#39;s exact percentage share in total portfolio valuation;</li><li>Hovering over a segment or clicking a legend item reveals exact dollar valuation and portfolio weight.</li></ul><div class="tip custom-block"><p class="custom-block-title">Portfolio Risk Rebalancing</p><p>If high-risk asset classes exceed your targeted allocation boundary, the color bar flags the imbalance immediately. This allows you to rebalance surplus workshop profit into secure debt securities or deposits.</p></div><hr><h2 id="mathematical-model-for-yield-calculation" tabindex="-1">Mathematical Model for Yield Calculation <a class="header-anchor" href="#mathematical-model-for-yield-calculation" aria-label="Permalink to &quot;Mathematical Model for Yield Calculation&quot;">​</a></h2><p>For each holding, the engine calculates absolute financial return and capital yield in real time:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Investment Performance</span><div class="formula-heading">Calculating Financial Return and Capital Yield</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Financial Return</span><span class="math-op">=</span><span class="math-var">Current Market Value</span><span class="math-op">−</span><span class="math-var">Invested Capital</span></div></div><div class="formula-card-bottom"><p>Percentage yield is calculated as the ratio of absolute financial return to initial invested principal multiplied by 100%. The system accounts for currency exchange rate shifts, recalculating foreign holdings against unified base currency rates.</p></div></div><p>The engine also tracks multi-tier allocation weights:</p><ul><li><strong>Class Share in Portfolio:</strong> proportion of the asset class relative to total investments;</li><li><strong>Platform Share:</strong> weight of the broker or custody vault;</li><li><strong>Instrument Share:</strong> position weight in the total portfolio and its relative weight inside the broker account.</li></ul><hr><h2 id="adding-and-configuring-investments" tabindex="-1">Adding and Configuring Investments <a class="header-anchor" href="#adding-and-configuring-investments" aria-label="Permalink to &quot;Adding and Configuring Investments&quot;">​</a></h2><p>Clicking <strong>&quot;Add&quot;</strong> opens a creation modal with two operational workflows:</p><ol><li><strong>&quot;Single Asset&quot; Mode:</strong> rapid entry of a standalone loan contract, precious metal holding, or direct venture equity.</li><li><strong>&quot;Group / Broker / Platform&quot; Mode:</strong> bulk creation of a brokerage account with multiple holdings via the <strong>&quot;Add asset to group&quot;</strong> button.</li></ol><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Purpose &amp; Format</th><th style="text-align:left;">Example Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>&quot;Asset Name&quot;</strong></td><td style="text-align:left;">Clear title of the security, fund, or equity holding</td><td style="text-align:left;"><em>S&amp;P 500 Index ETF</em>, <em>Treasury Bond 2030</em>, <em>25% Studio Equity</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Platform (Broker)&quot;</strong></td><td style="text-align:left;">Custody vault or brokerage institution</td><td style="text-align:left;"><em>Interactive Brokers</em>, <em>Fidelity</em>, <em>Cold Storage</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Asset Class&quot;</strong></td><td style="text-align:left;">Risk bucket for allocation calculations</td><td style="text-align:left;"><em>Equities</em>, <em>Bonds &amp; Funds</em>, <em>Private Equity</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Currency &amp; Rate&quot;</strong></td><td style="text-align:left;">Native currency and conversion rate to base currency</td><td style="text-align:left;"><em>USD ($)</em>, <em>EUR (€)</em>, <em>GBP (£)</em>, <em>USDT</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Invested Capital&quot;</strong></td><td style="text-align:left;">Total capital deployed to purchase the position</td><td style="text-align:left;"><em>$ 10,000.00</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Current Value&quot;</strong></td><td style="text-align:left;">Real-time market valuation on audit date</td><td style="text-align:left;"><em>$ 12,400.00</em></td></tr><tr><td style="text-align:left;"><strong>&quot;Terminal Link&quot;</strong></td><td style="text-align:left;">Direct web link to exchange terminal or fund fact sheet</td><td style="text-align:left;"><code>https://www.interactivebrokers.com/</code></td></tr><tr><td style="text-align:left;"><strong>&quot;Notes &amp; Strategy&quot;</strong></td><td style="text-align:left;">Target holding horizon, dividend payment dates, notes</td><td style="text-align:left;"><em>Quarterly dividend distribution</em></td></tr></tbody></table><hr><h2 id="realizing-gains-and-closing-positions" tabindex="-1">Realizing Gains and Closing Positions <a class="header-anchor" href="#realizing-gains-and-closing-positions" aria-label="Permalink to &quot;Realizing Gains and Closing Positions&quot;">​</a></h2><p>When an investment target is reached, a bond matures, or a partner repays principal with interest, close the position using the dedicated close workflow:</p><ol><li>Click the checkmark close icon on the asset line or card;</li><li>In the modal dialog, enter the <strong>actual realized sale price</strong> and transaction date;</li><li>The engine instantly computes the realized net gain or loss in base currency and percentage;</li><li><strong>Automated Fund Transfer:</strong> enable the option to deposit the total proceeds (principal plus gain) directly into an active account inside the <strong>&quot;Accounts &amp; Wallets&quot;</strong> tab;</li><li>The position is automatically archived, removing it from active balances while preserving accurate historical return ledgers.</li></ol><div class="info custom-block"><p class="custom-block-title">Automated Capital Transfer</p><p>Routing liquidation proceeds directly into liquid accounts closes the loop between capital preservation and daily cash flow, immediately freeing funds for new deployments or workshop financing.</p></div><hr><h2 id="managing-platforms-and-view-layouts" tabindex="-1">Managing Platforms and View Layouts <a class="header-anchor" href="#managing-platforms-and-view-layouts" aria-label="Permalink to &quot;Managing Platforms and View Layouts&quot;">​</a></h2><p>Broker cards provide agile management controls:</p><ul><li><strong>&quot;+&quot; Button:</strong> instantly adds a new instrument under the selected platform;</li><li><strong>Up / Down Arrows:</strong> reorder platforms and holdings to match your priority list;</li><li><strong>Pencil Button:</strong> comprehensive platform management — bulk renaming with cascading updates to child assets, class reassignments, and position audits;</li><li><strong>View Switcher (&quot;Grid Tiles&quot; / &quot;Compact Stripes&quot;):</strong> toggle between wide responsive card columns and a dense vertical accordion with a global <strong>&quot;↕&quot;</strong> expand/collapse button.</li></ul><div class="warning custom-block"><p class="custom-block-title">Preserving Return History</p><p>Never permanently delete an investment position upon exit. Use the formal close position workflow or move it to archive. This guarantees unbroken historical wealth analytics across multi-year cycles.</p></div>',37))])}const b=o(c,[["render",m]]);export{q as __pageData,b as default};
